def to_dict(self) -> Dict:
    """
    Convert the severity to a dictionary.

    Returns:
        Dict: The dictionary representation of the severity.
    """
    result = {'source': self.source}

    if self.cvssv3:
        result['cvssv3'] = self.cvssv3
        if 'base_score' in self.cvssv3:
            result['base_score'] = self.cvssv3['base_score']

    if self.cvssv2:
        result['cvssv2'] = self.cvssv2

    return result
